import Script from"./Script.js";Script.Load("https://cdnjs.cloudflare.com/ajax/libs/pdf.js/2.16.105/pdf.min.js");class PdfPreview{static Render(e,t){const i=document.getElementById(e),s=i.closest("div");s.style.position="relative";const n=document.createElement("div");n.className="loading-overlay",n.id="loading-"+e,s.appendChild(n);new IntersectionObserver((e,s)=>{e.forEach(e=>{if(e.isIntersecting){const e=i.getContext("2d");pdfjsLib.getDocument(t).promise.then(t=>{t.getPage(1).then(t=>{const s=t.getViewport({scale:" . $scale . "});i.height=s.height,i.width=s.width,n.height=s.height,n.width=s.width,t.render({canvasContext:e,viewport:s}).promise.then(()=>{n.style.display="none"})})}),s.unobserve(i)}})}).observe(i)}}